/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// </summary>
/// <param name = "_ledgerName">Ledger journal name ID</param>
/// <returns>list of ID's</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:LedgerName'),
    SysOperationDisplayOrderAttribute('1')
]
public LedgerJournalNameId getLedgerName(LedgerJournalNameId _ledgerName = ledgerName)
{
    ledgerName = _ledgerName;
    return ledgerName;
}

/// <summary>
/// Post and transfer parameter
/// MET_140777_XDOCBatchImprovement by yadavpa on 23/09/2024
/// </summary>
/// <param name = "_postAndTransfer">Post and transfer</param>
/// <returns>list of ID's</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('Post and transfer'),
    SysOperationDisplayOrderAttribute('2')
]
public boolean getPostOperation(boolean _postAndTransfer = postAndTransfer)
{
    postAndTransfer = _postAndTransfer;
    return postAndTransfer;
}
